 "Prevzemna koda in QR koda za prodajalca": [
  "Pickup code and QR code for the seller",
  "Abholcode und QR-Code für den Verkäufer"
 ],
 "Prodajalec lahko kodo skenira s kamero telefona ali vnese 6-mestno kodo. Kodo pokažite prodajalcu šele po pregledu predmeta. Z razkritjem kode potrjujete, da je predmet skladen z opisom, in prodajalec prejme izplačilo.": [
  "The seller can scan the code with the phone camera or enter the 6-digit code. Show the code to the seller only after inspecting the item. By revealing the code you confirm that the item matches the description, and the seller receives the payout.",
  "Der Verkäufer kann den Code mit der Handykamera scannen oder den 6-stelligen Code eingeben. Zeigen Sie den Code dem Verkäufer erst nach der Prüfung des Artikels. Mit der Offenlegung des Codes bestätigen Sie, dass der Artikel der Beschreibung entspricht, und der Verkäufer erhält die Auszahlung."
 ],
