 "Plačilo z nakazilom": [
  "Payment by transfer",
  "Zahlung per Überweisung"
 ],
 "Izbrali ste plačilo z bančnim nakazilom (SEPA). Znesek nakažite po navodilih, ki jih lahko kadar koli odprete s spodnjim gumbom. Plačilo se potrdi samodejno, ko denar prispe.": [
  "You chose to pay by bank transfer (SEPA). Transfer the amount following the instructions, which you can open at any time with the button below. The payment is confirmed automatically when the money arrives.",
  "Sie haben die Zahlung per Banküberweisung (SEPA) gewählt. Überweisen Sie den Betrag gemäß den Anweisungen, die Sie jederzeit mit der Schaltfläche unten öffnen können. Die Zahlung wird automatisch bestätigt, sobald das Geld eintrifft."
 ],
