 "Napaka pri potrditvi prejema.": [
  "Error confirming receipt.",
  "Fehler bei der Bestätigung des Erhalts."
 ],
 "Za oddajo ocene morate biti prijavljeni.": [
  "You must be signed in to submit a review.",
  "Zum Abgeben einer Bewertung müssen Sie angemeldet sein."
 ],
 "Hvala! Vaša ocena je bila uspešno oddana.": [
  "Thank you! Your review was submitted successfully.",
  "Danke! Ihre Bewertung wurde erfolgreich abgegeben."
 ],
 "Napaka pri oddaji ocene.": [
  "Error submitting the review.",
  "Fehler beim Abgeben der Bewertung."
 ],
 "Povezava s strežnikom je prekinjena.": [
  "The connection to the server was lost.",
  "Die Verbindung zum Server wurde unterbrochen."
 ],
 "Osveži stran": [
  "Refresh page",
  "Seite aktualisieren"
 ],
 "Z oddajo ponudbe potrjujete, da se strinjate s splošnimi pogoji poslovanja platforme dražbenik.si. Vaša ponudba je pravno zavezujoča. V primeru, da zmagate na dražbi, ste dolžni predmet prevzeti in plačati v skladu s pogoji prodajalca.": [
  "By placing a bid you confirm that you agree to the general terms of business of the dražbenik.si platform. Your bid is legally binding. If you win the auction, you are obliged to collect the item and pay in accordance with the seller's terms.",
  "Mit der Abgabe eines Gebots bestätigen Sie, dass Sie den Allgemeinen Geschäftsbedingungen der Plattform dražbenik.si zustimmen. Ihr Gebot ist rechtlich bindend. Wenn Sie die Auktion gewinnen, sind Sie verpflichtet, den Artikel abzuholen und gemäß den Bedingungen des Verkäufers zu bezahlen."
 ],
 "Ne prikaži več tega obvestila": [
  "Do not show this notice again",
  "Diesen Hinweis nicht mehr anzeigen"
 ],
 "Strinjam se in potrjujem ponudbo": [
  "I agree and confirm the bid",
  "Ich stimme zu und bestätige das Gebot"
 ],
 "Ponudba 2. ponudniku": [
  "Offer to the 2nd bidder",
  "Angebot an den 2. Bieter"
 ],
 "Za to dražbo ni 2. ponudnika. Dražbo lahko objavite ponovno.": [
  "There is no 2nd bidder for this auction. You can republish the auction.",
  "Für diese Auktion gibt es keinen 2. Bieter. Sie können die Auktion erneut veröffentlichen."
 ],
 "Predmet bo ponujen 2. najvišjemu ponudniku po njegovi ponudbi:": [
  "The item will be offered to the 2nd highest bidder at their bid:",
  "Der Artikel wird dem zweithöchsten Bieter zu dessen Gebot angeboten:"
 ],
 "Ponudnik bo o ponudbi obveščen po e-pošti in na spletni strani. Ima 24 ur za sprejem ponudbe in nato še 24 ur za plačilo. Če ponudbe ne sprejme, dražba preide med neprodane brez opomina; če jo sprejme in ne plača v roku, prejme opomin in dražba preide med neprodane in jo lahko objavite ponovno.": [
  "The bidder will be notified of the offer by email and on the website. They have 24 hours to accept the offer and then another 24 hours to pay. If they do not accept the offer, the auction moves to unsold without a warning; if they accept and do not pay in time, they receive a warning and the auction moves to unsold, where you can republish it.",
  "Der Bieter wird per E-Mail und auf der Webseite über das Angebot informiert. Er hat 24 Stunden Zeit, das Angebot anzunehmen, und danach weitere 24 Stunden für die Zahlung. Nimmt er das Angebot nicht an, wandert die Auktion ohne Verwarnung zu den nicht verkauften; nimmt er es an und zahlt nicht rechtzeitig, erhält er eine Verwarnung und die Auktion wandert zu den nicht verkauften, wo Sie sie erneut veröffentlichen können."
 ],
 "Potrdi in ponudi": [
  "Confirm and offer",
  "Bestätigen und anbieten"
 ],
 "Dokončen izbris dražbe": [
  "Permanent deletion of the auction",
  "Endgültige Löschung der Auktion"
 ],
 "Ali ste prepričani, da želite dokončno izbrisati": [
  "Are you sure you want to permanently delete",
  "Möchten Sie wirklich endgültig löschen:"
 ],
 "? Te akcije ni mogoče razveljaviti in dražba bo trajno odstranjena.": [
  "? This action cannot be undone and the auction will be removed permanently.",
  "? Diese Aktion kann nicht rückgängig gemacht werden und die Auktion wird dauerhaft entfernt."
 ],
 "Napaka pri izbrisu dražb.": [
  "Error deleting the auctions.",
  "Fehler beim Löschen der Auktionen."
 ],
 "Dražbe so bile uspešno izbrisane.": [
  "The auctions were deleted successfully.",
  "Die Auktionen wurden erfolgreich gelöscht."
 ],
