 "Izberite želeni način predaje ali prevzema predmeta.": [
  "Choose the desired handover or pickup method for the item.",
  "Wählen Sie die gewünschte Übergabe- oder Abholart für den Artikel."
 ],
 "Potrdi izbiro": [
  "Confirm selection",
  "Auswahl bestätigen"
 ],
 "Prejem potrjen!": [
  "Receipt confirmed!",
  "Erhalt bestätigt!"
 ],
 "Potrditev prejema": [
  "Confirm receipt",
  "Erhalt bestätigen"
 ],
 "Izplačilo prodajalcu je sproženo.": [
  "The payout to the seller has been triggered.",
  "Die Auszahlung an den Verkäufer wurde ausgelöst."
 ],
 "Sredstva bodo takoj sprejeta prodajalcu. Potrdite samo, če ste predmet že prejeli in preverili.": [
  "The funds will be released to the seller immediately. Confirm only if you have already received and inspected the item.",
  "Die Mittel werden sofort an den Verkäufer freigegeben. Bestätigen Sie nur, wenn Sie den Artikel bereits erhalten und geprüft haben."
 ],
 "S potrditvijo prejema potrjujete, da ste predmet pregledali, da je skladen z opisom in vsemi podatki prodajalca ter da ga sprejemate. Posel je s tem zaključen in izplačilo prodajalcu se sprosti takoj. Nadaljujem?": [
  "By confirming receipt you confirm that you inspected the item, that it matches the description and all of the seller's details, and that you accept it. The transaction is thereby completed and the payout to the seller is released immediately. Continue?",
  "Mit der Bestätigung des Erhalts bestätigen Sie, dass Sie den Artikel geprüft haben, dass er der Beschreibung und allen Angaben des Verkäufers entspricht und dass Sie ihn akzeptieren. Das Geschäft ist damit abgeschlossen und die Auszahlung an den Verkäufer wird sofort freigegeben. Fortfahren?"
 ],
